export const getGetTaDeskUrl = (roomCode: string,) => {




  return `/api/ta/desk/${roomCode}`
}

/**
 * @summary Get TA desk data — my claims, needs-a-TA questions, groups, and live queue
 */
export const getTaDesk = async (roomCode: string, options?: Parameters<typeof customFetch>[1]): Promise<TaDesk> => {

  return customFetch<TaDesk>(getGetTaDeskUrl(roomCode),
  {
    ...options,
    method: 'GET'


  }
);}





export const getGetTaDeskQueryKey = (roomCode: string,) => {
    return [
    `/api/ta/desk/${roomCode}`
    ] as const;
    }


export const getGetTaDeskQueryOptions = <TData = Awaited<ReturnType<typeof getTaDesk>>, TError = ErrorType<ErrorResponse>>(roomCode: string, options?: { query?:UseQueryOptions<Awaited<ReturnType<typeof getTaDesk>>, TError, TData>, request?: SecondParameter<typeof customFetch>}
) => {

const {query: queryOptions, request: requestOptions} = options ?? {};

  const queryKey =  queryOptions?.queryKey ?? getGetTaDeskQueryKey(roomCode);



    const queryFn: QueryFunction<Awaited<ReturnType<typeof getTaDesk>>> = ({ signal }) => getTaDesk(roomCode, { signal, ...requestOptions });





   return  { queryKey, queryFn, enabled: roomCode !== null && roomCode !== undefined, ...queryOptions} as UseQueryOptions<Awaited<ReturnType<typeof getTaDesk>>, TError, TData> & { queryKey: QueryKey }
}

export type GetTaDeskQueryResult = NonNullable<Awaited<ReturnType<typeof getTaDesk>>>
export type GetTaDeskQueryError = ErrorType<ErrorResponse>


/**
 * @summary Get TA desk data — my claims, needs-a-TA questions, groups, and live queue
 */

export function useGetTaDesk<TData = Awaited<ReturnType<typeof getTaDesk>>, TError = ErrorType<ErrorResponse>>(
 roomCode: string, options?: { query?:UseQueryOptions<Awaited<ReturnType<typeof getTaDesk>>, TError, TData>, request?: SecondParameter<typeof customFetch>}

 ):  UseQueryResult<TData, TError> & { queryKey: QueryKey } {

  const queryOptions = getGetTaDeskQueryOptions(roomCode,options)

  const query = useQuery(queryOptions) as  UseQueryResult<TData, TError> & { queryKey: QueryKey };

  return withQueryKey(query, queryOptions.queryKey);
}







